from __future__ import annotations
import subprocess
from typing import Any

# Every payload key run() accepts. A caller cannot pass what is not declared.
INPUT_SCHEMA = {"type": "object", "properties": {"dry_run": {"type": "boolean"}, "file_path": {"type": "string"}}, "required": ["file_path"]}


def run(payload: dict[str, Any]) -> dict[str, Any]:
    file_path = payload.get('file_path')
    dry_run = payload.get('dry_run', False)

    if not file_path:
        return {
            "ok": False,
            "error": "Missing 'file_path' in payload"
        }

    player = find_audio_player()
    if not player['found']:
        return {
            "ok": False,
            "error": f"No audio player found. Available players: {player['available_players'] or 'None'}"
        }

    command = [player['path'], file_path]

    if dry_run:
        return {
            "ok": True,
            "dry_run": True,
            "command": command
        }

    try:
        subprocess.run(command, check=True)
        return {
            "ok": True,
            "message": f"Audio file '{file_path}' played successfully using {player['name']}."
        }
    except subprocess.CalledProcessError as e:
        return {
            "ok": False,
            "error": f"Failed to play audio file: {e}",
            "command_output": str(e)
        }


def find_audio_player() -> dict[str, Any]:
    players = [
        {"name": "powershell", "path": "C:\\windows\\System32\\WindowsPowerShell\\v1.0\\powershell.EXE"},
        {"name": "cmd", "path": "C:\\windows\\system32\\cmd.EXE"}
    ]

    available_players = [player for player in players if subprocess.call([player['path'], "/c", "exit 0"], stdout=subprocess.DEVNULL, stderr=subprocess.STDOUT) == 0]

    return {
        "found": len(available_players) > 0,
        "path": available_players[0]['path'] if available_players else None,
        "name": available_players[0]['name'] if available_players else None,
        "available_players": [player['name'] for player in players]
    }
